// Issue Detail sections for the back office: A) the original feedback, B) the English technical context, C) evidence & attachments.
// The original description is shown exactly as written and is never edited here. The English context is a separate column: generated by the
// server (Edge Function feedback-english-context), or written by hand by staff; it can be copied for Claude Code or any other developer tool.
import { useEffect, useRef, useState } from 'react';
import { Copy, Paperclip, PenLine, RefreshCw, Wand2 } from 'lucide-react';
import {
  FeedbackAttachment, FeedbackIssue, attachmentsForCopy, contextState, contextWithAttachments, detectLanguage, englishContextCopy, englishContextTemplate,
  parseContext, requestEnglishContext, setEnglishContext,
} from '../lib/feedbackApi';
import { copyText } from '../wallet/bank';
import { dateTimeFmt } from '../lib/util';
import { t } from '../lib/i18n';
import { toast, useLang } from '../domain/store';
import { Badge, Banner, Button, Card, KV, Textarea, useConfirm } from './kit';
import { AttachmentList } from './feedbackParts';

const LANG_LABEL = { th: 'Thai', en: 'English', mixed: 'Thai and English', unknown: '—' } as const;

/** Section A: what the reporter wrote, untouched, with the facts that identify the report. */
export function OriginalFeedbackCard({ issue }: { issue: FeedbackIssue }) {
  const lang = useLang();
  return (
    <Card title="Original feedback" sub="Exactly as the reporter wrote it. This text is never changed.">
      <div style={{ whiteSpace: 'pre-wrap', overflowWrap: 'anywhere' }} data-testid="original-description">{issue.description}</div>
      {issue.remark && <div className="muted mt8" style={{ whiteSpace: 'pre-wrap' }}>{issue.remark}</div>}
      <div className="mt8">
        <KV items={[
          ['Original language', t(lang, LANG_LABEL[detectLanguage(`${issue.title} ${issue.description}`)])],
          ['Reporter', `${issue.submitter_label} (${t(lang, issue.source === 'customer' ? 'Customer' : 'Staff')})`],
          ['Submitted on', dateTimeFmt(issue.created_at)],
        ]} />
      </div>
    </Card>
  );
}

/** Section C: the screenshots and files that came with the report. */
export function EvidenceCard({ attachments, loading }: { attachments: FeedbackAttachment[]; loading: boolean }) {
  const lang = useLang();
  return (
    <Card title="Evidence & attachments" sub={loading ? undefined : t(lang, '{n} file(s) attached to the original report', { n: attachments.length })}>
      {loading ? <div className="center" style={{ padding: 12 }}><div className="spinner" /></div>
        : attachments.length ? <AttachmentList items={attachments} evidence />
          : <div className="muted"><Paperclip size={13} style={{ verticalAlign: -2 }} /> {t(lang, 'No screenshots or files were attached.')}</div>}
    </Card>
  );
}

const hintFor = (error: string | null) =>
  error && /^(AI_NOT_CONFIGURED|AI_NOT_DEPLOYED|AI_UNAVAILABLE)/.test(error)
    ? 'The English-context service is not set up or cannot be reached. An administrator must add the AI key and deploy the function (docs/feedback-english-context.md). You can still write the English text by hand.'
    : error && /^RATE_LIMITED/.test(error) ? 'Too many attempts. Try again later, or write the English text by hand.'
      : 'The English text could not be generated. Try again, or write it by hand.';

/** Section B: the English technical context, with Copy / Regenerate / Edit. */
export function EnglishContextCard({ issue, attachments, onChanged }: { issue: FeedbackIssue; attachments: FeedbackAttachment[]; onChanged: () => void }) {
  const lang = useLang();
  const confirm = useConfirm();
  const [generating, setGenerating] = useState(false);
  const [localError, setLocalError] = useState<string | null>(null);
  const [editing, setEditing] = useState(false);
  const [draft, setDraft] = useState('');
  const [saving, setSaving] = useState(false);
  const [copying, setCopying] = useState(false);
  const [manualCopy, setManualCopy] = useState<string | null>(null);
  const st = contextState(issue);
  const status = generating ? 'processing' : localError && st.status !== 'completed' ? 'failed' : st.status;
  const error = localError ?? st.error;
  const text = issue.english_context ?? '';
  const hasText = text.trim() !== '';
  const sections = parseContext(text);

  // another person (or the customer's own submission) started a generation: look again every few seconds until it ends
  const refresh = useRef(onChanged);
  refresh.current = onChanged;
  useEffect(() => {
    if (generating || st.status !== 'processing') return;
    const id = window.setInterval(() => refresh.current(), 4000);
    return () => window.clearInterval(id);
  }, [generating, st.status]);

  const generate = async () => {
    if (hasText && issue.english_context_source === 'manual') {
      const r = await confirm({ title: t(lang, 'Replace the hand-written English text?'), body: t(lang, 'Generating again overwrites the text that staff wrote. The original feedback is not changed.'), confirmLabel: t(lang, 'Regenerate') });
      if (!r.ok) return;
    }
    setGenerating(true); setLocalError(null);
    const res = await requestEnglishContext(issue.id);
    setGenerating(false);
    if (res.status === 'failed') setLocalError(res.error ?? 'AI_ERROR: unknown');
    else if (res.status === 'processing') toast('info', t(lang, 'The English context is already being generated.'));
    onChanged();
  };

  const finishCopy = (ok: boolean, okText: string, copied: string) => {
    if (ok) { toast('success', okText); setManualCopy(null); } else { toast('error', t(lang, 'Could not copy automatically — the text is shown below so you can copy it by hand.')); setManualCopy(copied); }
  };
  const copyContext = async () => { const s = englishContextCopy(issue); finishCopy(await copyText(s), t(lang, 'English context copied to the clipboard'), s); };
  const copyWithFiles = async () => {
    setCopying(true);
    try {
      const atts = await attachmentsForCopy(attachments);
      const s = contextWithAttachments(issue, atts);
      finishCopy(await copyText(s), t(lang, 'Copied the English context and {n} attachment link(s). Images are linked, not embedded.', { n: atts.length }), s);
    } finally { setCopying(false); }
  };

  const save = async () => {
    setSaving(true);
    try { await setEnglishContext(issue.id, draft); toast('success', t(lang, 'English context saved')); setEditing(false); onChanged(); }
    catch (e) { toast('error', (e as Error).message); }
    finally { setSaving(false); }
  };

  const badge = status === 'completed' ? <Badge tone="good" dot>{t(lang, 'Ready')}</Badge>
    : status === 'processing' ? <Badge tone="warn" dot>{t(lang, 'Generating…')}</Badge>
      : status === 'failed' ? <Badge tone="bad" dot>{t(lang, 'Failed')}</Badge>
        : <Badge tone="info" dot>{t(lang, 'Not generated yet')}</Badge>;
  const source = status !== 'completed' || !hasText ? null
    : issue.english_context_source === 'manual' ? t(lang, 'Written by hand') : `${t(lang, 'Generated by AI')}${issue.english_context_model ? ` · ${issue.english_context_model}` : ''}`;

  return (
    <Card title="English technical context" sub="A structured English version for developers and coding assistants. The original feedback above is not changed." actions={<span data-testid="ctx-status" data-status={status}>{badge}</span>}>
      <div className="col gap-8">
        {status === 'failed' && <div data-testid="ctx-error"><Banner tone="bad">{`${t(lang, hintFor(error))}${error ? ` (${error})` : ''}`}</Banner></div>}
        {status === 'processing' && <div className="row gap-6 muted" style={{ fontSize: 13 }}><div className="spinner" style={{ width: 14, height: 14 }} /> {t(lang, 'The English version is being prepared…')}</div>}
        {status === 'pending' && !hasText && <div className="muted" data-testid="ctx-pending">{t(lang, 'The English version has not been generated for this issue yet.')}</div>}

        {editing ? (
          <>
            <Textarea rows={14} value={draft} onChange={(e) => setDraft(e.target.value)} data-testid="ctx-editor" />
            <div className="muted" style={{ fontSize: 12 }}>{t(lang, 'Write only what the report supports. Use "Not provided" where nothing is known.')}</div>
            <div className="row gap-6">
              <Button variant="primary" size="sm" loading={saving} disabled={!draft.trim() || saving} onClick={save} data-testid="ctx-save">{t(lang, 'Save English context')}</Button>
              <Button size="sm" disabled={saving} onClick={() => setEditing(false)}>{t(lang, 'Cancel')}</Button>
            </div>
          </>
        ) : hasText && (
          <div data-testid="ctx-text" style={{ overflowWrap: 'anywhere' }}>
            {source && <div className="muted" style={{ fontSize: 12, marginBottom: 6 }}>{source}{issue.english_context_at ? ` · ${dateTimeFmt(issue.english_context_at)}` : ''}</div>}
            {sections ? sections.map((s) => (
              <div key={s.title} style={{ marginBottom: 10 }}>
                <div style={{ fontSize: 11.5, fontWeight: 650, textTransform: 'uppercase', letterSpacing: '.03em' }} className="muted">{s.title}</div>
                <div style={{ whiteSpace: 'pre-wrap' }} className={s.body === 'Not provided' ? 'muted' : undefined}>{s.body || 'Not provided'}</div>
              </div>
            )) : <div style={{ whiteSpace: 'pre-wrap' }}>{text}</div>}
          </div>
        )}

        {!editing && (
          <div className="row wrap" style={{ gap: 8 }}>
            <Button size="sm" variant="primary" disabled={!hasText || status === 'processing'} onClick={copyContext} data-testid="ctx-copy"><Copy size={13} />{' '}{t(lang, 'Copy English Context')}</Button>
            <Button size="sm" disabled={!hasText || status === 'processing' || copying} loading={copying} onClick={copyWithFiles} data-testid="ctx-copy-files"><Paperclip size={13} />{' '}{t(lang, 'Copy Context + Attachments')}</Button>
            <Button size="sm" disabled={generating || status === 'processing'} loading={generating} onClick={generate} data-testid="ctx-regenerate">
              {hasText ? <RefreshCw size={13} /> : <Wand2 size={13} />}{' '}{t(lang, status === 'failed' ? 'Retry' : hasText ? 'Regenerate' : 'Generate')}
            </Button>
            <Button size="sm" variant="ghost" disabled={generating} onClick={() => { setDraft(hasText ? text : englishContextTemplate()); setEditing(true); }} data-testid="ctx-edit"><PenLine size={13} />{' '}{t(lang, hasText ? 'Edit' : 'Write by hand')}</Button>
          </div>
        )}
        {!editing && hasText && <div className="muted" style={{ fontSize: 12 }}>{t(lang, 'Attachment links are private, expire after 24 hours, and the images are not embedded in the copied text.')}</div>}
        {manualCopy !== null && <Textarea readOnly rows={8} value={manualCopy} onFocus={(e) => e.currentTarget.select()} data-testid="ctx-manual-copy" />}
      </div>
    </Card>
  );
}
